                                              '**Stage 5: Execute Multi-Table Relational JOIN Queries**\n'
                                              '\n'
                                              '**Location:** local terminal\n'
                                              '\n'
                                              '**Actions:**\n'
                                              'Execute an INNER JOIN and LEFT JOIN combining customers, orders, and '
                                              'line items.\n'
                                              '```bash\n'
                                              "cat <<'EOF' > scratch/day16_lab/run_joins.py\n"
                                              'import sqlite3\n'
                                              'import json\n'
                                              '\n'
                                              'conn = sqlite3.connect("scratch/day16_lab/bakery.db")\n'
                                              'cursor = conn.cursor()\n'
                                              '\n'
                                              '# Relational Join: Customer Order Summary\n'
                                              "query = '''\n"
                                              'SELECT \n'
                                              '    o.order_id,\n'
                                              '    c.name AS customer_name,\n'
                                              '    c.email,\n'
