                                              '    o.total_cents\n'
                                              'FROM orders o\n'
                                              'INNER JOIN customers c ON o.customer_id = c.customer_id\n'
                                              'ORDER BY o.order_id ASC;\n'
                                              "'''\n"
                                              'cursor.execute(query)\n'
                                              'rows = cursor.fetchall()\n'
                                              '\n'
                                              'results = [\n'
                                              '    {\n'
                                              '        "order_id": r[0],\n'
                                              '        "customer_name": r[1],\n'
