                                              "cat <<'EOF' > scratch/day16_lab/run_having.py\n"
                                              'import sqlite3\n'
                                              'import json\n'
                                              '\n'
                                              'conn = sqlite3.connect("scratch/day16_lab/bakery.db")\n'
                                              'cursor = conn.cursor()\n'
