                                              "query = '''\n"
                                              'SELECT \n'
                                              '    o.order_id,\n'
                                              '    c.name AS customer_name,\n'
                                              '    COUNT(oi.item_id) AS line_item_count,\n'
                                              '    SUM(oi.quantity * oi.unit_price_cents) AS calculated_total_cents\n'
                                              'FROM orders o\n'
                                              'INNER JOIN customers c ON o.customer_id = c.customer_id\n'
                                              'INNER JOIN order_items oi ON o.order_id = oi.order_id\n'
                                              'GROUP BY o.order_id, c.name\n'
                                              'HAVING calculated_total_cents >= 2000\n'
                                              'ORDER BY calculated_total_cents DESC;\n'
                                              "'''\n"
                                              'cursor.execute(query)\n'
                                              'rows = cursor.fetchall()\n'
                                              '\n'
                                              'filtered_orders = [\n'
                                              '    {\n'
                                              '        "order_id": r[0],\n'
                                              '        "customer_name": r[1],\n'
                                              '        "line_item_count": r[2],\n'
                                              '        "calculated_total_cents": r[3]\n'
                                              '    }\n'
                                              '    for r in rows\n'
                                              ']\n'
                                              '\n'
                                              'with open("scratch/day16_lab/stage7_having_orders.json", "w") as f:\n'
                                              '    json.dump(filtered_orders, f, indent=2)\n'
                                              '\n'
                                              'print(f"Executed HAVING aggregation: {len(filtered_orders)} high-value '
                                              'orders identified.")\n'
                                              'conn.close()\n'
                                              'EOF\n'
                                              'python3 scratch/day16_lab/run_having.py\n'
                                              'cat scratch/day16_lab/stage7_having_orders.json\n'
                                              '```\n'
