                                              'Execute an atomic multi-table transaction that deducts inventory, '
                                              'records an accounting ledger charge, and commits atomically.\n'
                                              '```bash\n'
                                              "cat <<'EOF' > scratch/day16_lab/tx_commit.py\n"
                                              'import sqlite3\n'
                                              'import json\n'
                                              '\n'
                                              'conn = sqlite3.connect("scratch/day16_lab/tx_test.db")\n'
                                              'conn.isolation_level = None # Manual transaction control\n'
                                              'cursor = conn.cursor()\n'
                                              '\n'
                                              'try:\n'
                                              '    cursor.execute("BEGIN TRANSACTION;")\n'
                                              '    \n'
                                              '    # 1. Deduct inventory\n'
