             'stock FROM inventory</text>\n'
             '<text fill="#f43f5e" font-size="9" x="45" y="98">Both see stock = 1 (Initial available item '
             'count)</text>\n'
             '<rect fill="#21262d" height="42" rx="4" stroke="#f43f5e" stroke-width="1" width="400" x="35" '
             'y="115"></rect>\n'
             '<text fill="#fce7f3" font-size="9.5" font-weight="600" x="45" y="133">Both execute: UPDATE inventory SET '
             'stock = stock - 1</text>\n'
             '<text fill="#f43f5e" font-size="9" x="45" y="148">Tx 1 commits (stock=0); Tx 2 commits (stock = -1 '
             '!)</text>\n'
             '<rect fill="#1c2128" height="75" rx="4" stroke="#f43f5e" stroke-width="1.2" width="400" x="35" '
